fs.mkdirSync(`${root}/logs`,{recursive:true});fs.mkdirSync(`${root}/conditions`,{recursive:true});
const envKeys=['RELEASE_QUALITY','RELEASE_OUT','RELEASE_SECONDS','RELEASE_PERF_ONLY','RELEASE_CPU_PROFILE','RELEASE_SIDES','RELEASE_CANDIDATE_ORIGIN'];
const entry={label,started:new Date().toISOString(),revision:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),command:['sh','tools/perf/quiet-run.sh',...command],env:Object.fromEntries(envKeys.filter(k=>process.env[k]!==undefined).map(k=>[k,process.env[k]]))};
