import json,pathlib,math
R=pathlib.Path('test-results/perf8')
def read(p):return json.loads(p.read_text())
def stats(a):
 s=sorted(a);return dict(samples=len(a),p95=s[math.ceil(.95*len(s))-1],maximum=max(s),spikes66=sum(v>=66 for v in a)) if a else None
def compare(p,c):
 issues=[]
 if not p or not c:return dict(verdict='INCOMPLETE',issues=['missing frames'])
 if c['p95']>p['p95']+1:issues.append('p95 > PROD+1 ms')
 if c['maximum']>p['maximum']+16.8:issues.append('max > PROD+1 frame')
 if c['maximum']>=66 and p['maximum']<66:issues.append('new >=66 ms spike')
 return dict(verdict='FAIL' if issues else 'PASS',issues=issues,inherited66=c['maximum']>=66 and p['maximum']>=66)
loads=[]
for p in sorted((R/'initial').glob('*/loads/*.json')):
 for r in read(p):loads.append(dict(r,rawSource=str(p)))
native=[]
for p in sorted((R/'initial').glob('*/strips/webgpu/*.json')):
 for r in read(p):native.append(dict(r,rawSource=str(p)))
rows=[]
for backend,level,tier in [('webgpu',l,t) for t in ['low','high'] for l in ['L3','L4','L7','L9','L10']]+[('webgl2',l,'low') for l in ['L4','L10']]:
 row=dict(backend=backend,level=level,tier=tier,loads={},native={});issues=[]
 for side in ['prod','candidate']:
  selected=[r for r in loads if (r['backend'],r['level'],r['tier'],r['side'])==(backend,level,tier,side)]
  row['loads'][side]={r['temperature']:r['ms'] for r in selected}
  if len(selected)!=2:issues.append(side+': missing cold/warm')
  if any(r['errors'] or r['quality']!=tier for r in selected):issues.append(side+': load error/tier mismatch')
 if all(len(row['loads'][s])==2 for s in ['prod','candidate']):
  for t in ['cold','warm']:
   c,p=row['loads']['candidate'][t],row['loads']['prod'][t]
   if c>6000:issues.append(t+': >6 s')
   if c>p+500:issues.append(t+': >PROD+0.5 s')
 if backend=='webgpu':
  sides={r['side']:r for r in native if r['level']==level and r['tier']==tier}
  for side,r in sides.items():
   f=r.get('performance');row['native'][side]=stats(f['frames']) if f else None
   if r.get('failure') or r['errors'] or r['diagnostic'] or not f or f['durationMs']<60000 or f['nonGameplayFrames']:issues.append(side+': invalid native capture')
  if len(sides)==2:issues+=compare(row['native']['prod'],row['native']['candidate'])['issues']
  else:issues.append('missing native capture')
 row.update(verdict='FAIL' if issues else 'PASS',issues=issues)
 if any('missing' in s for s in issues):row['verdict']='INCOMPLETE'
 rows.append(row)
moments=[]
for name,level,tier,select in [('L10 captured charge through completion (+2 s)','L10','high',lambda f:[f['frames'][i] for i,v in enumerate(f['chargeFrames']) if v['at']<=next(x['at'] for x in f['chargeFrames'] if x['charge']>=3600)+2000]),('L10 charge 43/60','L10','high',lambda f:[f['frames'][i] for i,v in enumerate(f['chargeFrames']) if v['charge']//60==43]),('L10 charge 55/60','L10','high',lambda f:[f['frames'][i] for i,v in enumerate(f['chargeFrames']) if v['charge']//60==55]),('L4 war phase within first 60 s','L4','high',lambda f:[f['frames'][i] for i,v in enumerate(f['warFrames']) if v['phase']=='war' and 0<=v['warTicks']<=3600])]:
 sides={r['side']:stats(select(r['performance'])) for r in native if r['level']==level and r['tier']==tier and r.get('performance')}
 row=dict(name=name,sides=sides)
 row.update(compare(sides.get('prod'),sides.get('candidate')));moments.append(row)
result=dict(matrix=rows,moments=moments,loadRows=len(loads),nativeRows=len(native))
(R/'summary.json').write_text(json.dumps(result,indent=2))
print(json.dumps(result,indent=2))
